import{_ as e,o as i,c as a,an as t}from"./chunks/framework.TMZMsZ4a.js";const k=JSON.parse('{"title":"MAGEMin_C.jl: options","description":"","frontmatter":{},"headers":[],"relativePath":"MAGEMin_C/options.md","filePath":"MAGEMin_C/options.md","lastUpdated":null}'),l={name:"MAGEMin_C/options.md"};function n(o,s,h,d,p,c){return i(),a("div",null,[...s[0]||(s[0]=[t('<h1 id="MAGEMin_C.jl:-options" tabindex="-1">MAGEMin_C.jl: options <a class="header-anchor" href="#MAGEMin_C.jl:-options" aria-label="Permalink to &quot;MAGEMin_C.jl: options {#MAGEMin_C.jl:-options}&quot;">​</a></h1><h2 id="General-options-/-functionality" tabindex="-1">General options / functionality <a class="header-anchor" href="#General-options-/-functionality" aria-label="Permalink to &quot;General options / functionality {#General-options-/-functionality}&quot;">​</a></h2><h3 id="Name-solvus" tabindex="-1">Name solvus <a class="header-anchor" href="#Name-solvus" aria-label="Permalink to &quot;Name solvus {#Name-solvus}&quot;">​</a></h3><ul><li>When performing calculations, it is usually recommended to use the argument <code>name_solvus = true</code>, e.g.,</li></ul><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">out </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> single_point_minimization</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(P, T, data, X</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">X, Xoxides</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Xoxides, sys_in</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sys_unit, name_solvus </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>This option checks the composition of the stable solution phases and tries to name them accordingly. For instance, this allows distinguishing feldspar as plagioclase or alkali-feldspar. Details about how solvus phases are named are provided in the Method section.</p><h3 id="Solver-option" tabindex="-1">Solver option <a class="header-anchor" href="#Solver-option" aria-label="Permalink to &quot;Solver option {#Solver-option}&quot;">​</a></h3><ul><li>It is usually best to use the solver option <code>solver = 0</code> when performing calculations. This is easily activated by initializing <code>MAGEMin_C.jl</code> such as:</li></ul><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">data        </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">   Initialize_MAGEMin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;mb&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, verbose</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, solver </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><h3 id="Buffers" tabindex="-1">Buffers <a class="header-anchor" href="#Buffers" aria-label="Permalink to &quot;Buffers {#Buffers}&quot;">​</a></h3><ul><li>When using buffers, note that you need to provide enough oxide to oversaturate the system across the whole P-T(-X) range of interest. While this applies to oxygen buffers, it also applies to activity buffers (e.g., <code>aTiO2</code>, <code>aH2O</code>, <code>aSiO2</code>, etc.).</li></ul><h2 id="Database-dependent-choices" tabindex="-1">Database dependent choices <a class="header-anchor" href="#Database-dependent-choices" aria-label="Permalink to &quot;Database dependent choices {#Database-dependent-choices}&quot;">​</a></h2><h3 id="Metabasite-mb" tabindex="-1">Metabasite (mb) <a class="header-anchor" href="#Metabasite-mb" aria-label="Permalink to &quot;Metabasite (mb) {#Metabasite-mb}&quot;">​</a></h3><ul><li>When using the metabasite database (Green et al., 2016), it is important to activate the correct clinopyroxene depending on the temperature conditions. By default, <code>aug</code> (the high-temperature solution model) is active. If you need to use the low-temperature solution model <code>dio</code> instead, you can initialize <code>MAGEMin_C.jl</code> such as:</li></ul><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">data        </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">   Initialize_MAGEMin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;mb&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, verbose</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, mbCpx </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Note</p><p>The default value is <code>mbCpx = 1</code></p></div><ul><li>Similarly, <code>mbIlm</code>, <code>mpSp</code>, and <code>mpIlm</code> switch between paired solution models on the metabasite/metapelite databases:</li></ul><table tabindex="0"><thead><tr><th style="text-align:right;">Option</th><th style="text-align:right;">Database</th><th style="text-align:right;"><code>= 0</code></th><th style="text-align:right;"><code>= 1</code></th><th style="text-align:right;">Default</th></tr></thead><tbody><tr><td style="text-align:right;"><code>mbCpx</code></td><td style="text-align:right;"><code>mb</code></td><td style="text-align:right;">Omphacite (<code>dio</code>, low-T)</td><td style="text-align:right;">Augite (<code>aug</code>, high-T)</td><td style="text-align:right;"><code>1</code></td></tr><tr><td style="text-align:right;"><code>mbIlm</code></td><td style="text-align:right;"><code>mb</code></td><td style="text-align:right;">Ilmenite-hematite (<code>ilmm</code>)</td><td style="text-align:right;">Ilmenite (<code>ilm</code>)</td><td style="text-align:right;"><code>0</code></td></tr><tr><td style="text-align:right;"><code>mpSp</code></td><td style="text-align:right;"><code>mp</code></td><td style="text-align:right;">Spinel (<code>sp</code>)</td><td style="text-align:right;">Spinel (<code>spl</code>)</td><td style="text-align:right;"><code>0</code></td></tr><tr><td style="text-align:right;"><code>mpIlm</code></td><td style="text-align:right;"><code>mp</code></td><td style="text-align:right;">Ilmenite-hematite (<code>ilmm</code>)</td><td style="text-align:right;">Ilmenite (<code>ilm</code>)</td><td style="text-align:right;"><code>0</code></td></tr></tbody></table><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">data        </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">   Initialize_MAGEMin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;mb&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, verbose</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, mbIlm </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>None of <code>mbCpx</code>/<code>mbIlm</code>/<code>mpSp</code>/<code>mpIlm</code> apply to the <code>all</code> database - its dispatch deliberately keeps both phase variants each toggle would otherwise switch between as independent, separately selectable phases (e.g. both <code>dio_G16</code> and <code>aug_G16</code> are always present). Use <a href="/MAGEMin_C.jl/stable/MAGEMin_C/options#Selecting-which-phases-to-consider"><code>select_phases</code>/<code>pp_list=</code>/<code>ss_list=</code></a> or <code>remove_phases</code>/<code>rm_list=</code> to pick between them there instead.</p></div><h2 id="Selecting-which-phases-to-consider" tabindex="-1">Selecting which phases to consider <a class="header-anchor" href="#Selecting-which-phases-to-consider" aria-label="Permalink to &quot;Selecting which phases to consider {#Selecting-which-phases-to-consider}&quot;">​</a></h2><p>Two complementary ways to restrict which pure/solution phases MAGEMin considers during minimization - an exclude-list and an include-list. Use whichever is shorter to write for your case; passing both at once raises an error.</p><h3 id="Exclude-a-list-of-phases-remove_phases/rm_list" tabindex="-1">Exclude a list of phases (<code>remove_phases</code>/<code>rm_list=</code>) <a class="header-anchor" href="#Exclude-a-list-of-phases-remove_phases/rm_list" aria-label="Permalink to &quot;Exclude a list of phases (`remove_phases`/`rm_list=`) {#Exclude-a-list-of-phases-remove_phases/rm_list}&quot;">​</a></h3><p><code>remove_phases(list, dtb)</code> resolves phase names against the given database and returns an index list (<code>rm_list</code>) to pass to <code>single_point_minimization</code>/<code>multi_point_minimization</code>/ <code>AMR_minimization</code>. See <a href="/MAGEMin_C.jl/stable/MAGEMin_C/examples#E.5-Removing-solution-phase-from-consideration">example E.5</a>.</p><h3 id="Keep-only-a-list-of-phases-select_phases/pp_list/ss_list" tabindex="-1">Keep only a list of phases (<code>select_phases</code>/<code>pp_list=</code>/<code>ss_list=</code>) <a class="header-anchor" href="#Keep-only-a-list-of-phases-select_phases/pp_list/ss_list" aria-label="Permalink to &quot;Keep only a list of phases (`select_phases`/`pp_list=`/`ss_list=`) {#Keep-only-a-list-of-phases-select_phases/pp_list/ss_list}&quot;">​</a></h3><p><code>select_phases</code> is the inverse: give it the pure phases (<code>pp_list=</code>) and/or solution phases (<code>ss_list=</code>) you want to <strong>keep active</strong>, and every other phase in that category is deactivated automatically. <code>pp_list</code> and <code>ss_list</code> are independent - passing only one leaves the other phase category untouched.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">data    </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Initialize_MAGEMin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;mp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, verbose</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">out     </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> single_point_minimization</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(P, T, data, X</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">X, Xoxides</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Xoxides, sys_in</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sys_in,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">                                     ss_list</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;liq_W14&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;g_W14&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;bi_W14&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">])</span></span></code></pre></div><p>is equivalent to writing out the complement by hand with <code>remove_phases</code>, but self-updates if the database&#39;s phase list changes. The 13 oxygen-fugacity buffer / fixed-activity pure phases (<code>qfm</code>, <code>mw</code>, <code>qif</code>, <code>nno</code>, <code>hm</code>, <code>iw</code>, <code>cco</code>, <code>aH2O</code>, <code>aO2</code>, <code>aMgO</code>, <code>aFeO</code>, <code>aAl2O3</code>, <code>aTiO2</code>) never need to be listed in <code>pp_list</code> - <code>select_phases</code> always leaves them untouched, since their activation is governed solely by the <code>buffer=&quot;...&quot;</code> keyword (see <a href="/MAGEMin_C.jl/stable/MAGEMin_C/options#Buffers">Buffers</a> above), not by phase selection.</p><div class="tip custom-block"><p class="custom-block-title">Note</p><p><code>select_phases</code>/<code>pp_list=</code>/<code>ss_list=</code> and <code>remove_phases</code>/<code>rm_list=</code> are mutually exclusive on a single call - combining them raises an error rather than silently guessing intent.</p></div><h3 id="Discovering-phase-names-print_phase_info" tabindex="-1">Discovering phase names (<code>print_phase_info</code>) <a class="header-anchor" href="#Discovering-phase-names-print_phase_info" aria-label="Permalink to &quot;Discovering phase names (`print_phase_info`) {#Discovering-phase-names-print_phase_info}&quot;">​</a></h3><p>Both <code>remove_phases</code> and <code>select_phases</code> need exact phase names, which can be hard to guess for an unfamiliar database (particularly <code>all</code>, with its citation-tagged names like <code>liq_W14</code> vs <code>liq_G16</code>). <code>print_phase_info(dtb; level=0|1)</code> prints them directly:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">print_phase_info</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;mp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)            </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># database info, solution-phase names, pure-phase names</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">print_phase_info</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;mp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; level</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># same, plus every solution phase&#39;s endmember list</span></span></code></pre></div>',32)])])}const g=e(l,[["render",n]]);export{k as __pageData,g as default};
